public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }

    int maxLength = 0;

    for (String s : strings) {
        int n = s.length();
        boolean[] forward = new boolean[n];
        boolean[] backward = new boolean[n];

        for (int i = 0; i < n; i++) {
            forward[i] = true;
            backward[n - 1 - i] = true;
        }

        for (int i = 1; i < n; i++) {
            for (int j = 0; j <= n - 1 - i; j++) {
                if (s.charAt(j) == s.charAt(j + i)) {
                    forward[j] = forward[j] && forward[j + 1];
                    backward[j + i] = backward[j + i] && backward[j + i - 1];
                } else {
                    forward[j] = false;
                    backward[j + i] = false;
                }
            }
        }

        for (int i = 1; i < n; i++) {
            for (int j = 0; j <= n - 1 - i; j++) {
                if (forward[j]) {
                    int len = j + 2 * i + 1;
                    if (len > maxLength) {
                        maxLength = len;
                    }
                }
                if (backward[j]) {
                    int len = j + 2 * i + 1;
                    if (len > maxLength) {
                        maxLength = len;
                    }
                }
            }
        }
    }

    return maxLength;
}

public int findLargestSubstring(List<String> strings) {
    int maxLength = 0;
    for (String s : strings) {
        for (int i = 0; i < s.length(); i++) {
            String prefix = s.substring(0, i + 1);
            String reversedPrefix = new StringBuilder(prefix).reverse().toString();
            if (strings.stream().anyMatch(other -> other.contains(prefix) || other.contains(reversedPrefix))) {
                maxLength = Math.max(maxLength, prefix.length());
            }
        }
    }
    return maxLength;
}

