        return 0;
    }

    String largest = "";
    String inverseLargest = "";

    for (String str : strings) {
        for (int i = 0; i < str.length(); i++) {
            for (int j = i + 1; j <= str.length(); j++) {
                String substring = str.substring(i, j);
                String inverseSubstring = new StringBuilder(substring).reverse().toString();

                if (!substring.equals(inverseSubstring) && (largest.length() < substring.length() || inverseLargest.length() < inverseSubstring.length())) {
                    if (strings.stream().anyMatch(s -> s.contains(substring) || s.contains(inverseSubstring))) {
                        if (substring.length() > inverseSubstring.length()) {
                            largest = substring;
                        } else {
                            inverseLargest = inverseSubstring;
                        }
                    }
                }
            }
        }
    }

    return Math.max(largest.length(), inverseLargest.length());
}

public static int countOilDeposits(char[][] grid) {
    int count = 0;
    for (int i = 0; i < grid.length; i++) {
        for (int j = 0; j < grid[i].length; j++) {
            if (grid[i][j] == '@') {
                count++;
                markDeposit(grid, i, j);
            }
        }
    }
    return count;
}

private static void markDeposit(char[][] grid, int i, int j) {
    if (i < 0 || i >= grid.length || j < 0 || j >= grid[i].length || grid[i][j] == '*') {
        return;
    }
    grid[i][j] = '*';
    markDeposit(grid, i - 1, j);
    markDeposit(grid, i + 1, j);
    markDeposit(grid, i, j - 1);
    markDeposit(grid, i, j + 1);
}

public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0 || grid[0].length == 0) {
        return 0;
    }

    int rows = grid.length;
    int cols = grid[0].length;
    boolean[][] visited = new boolean[rows][cols];
    int oilDeposits = 0;

    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            if (grid[i][j] == '@' && !visited[i][j]) {
                dfs(grid, visited, i, j);
                oilDeposits++;
            }
        }
    }

    return oilDeposits;
}

private static void dfs(char[][] grid, boolean[][] visited, int i, int j) {
    if (i < 0 || i >= grid.length || j < 0 || j >= grid[0].length || grid[i][j] == '*' || visited[i][j]) {
        return;
    }

    visited[i][j] = true;

    // Explore all 8 directions
    dfs(grid, visited, i - 1, j);
    dfs(grid, visited, i + 1, j);
    dfs(grid, visited, i, j - 1);
    dfs(grid, visited, i, j + 1);
    dfs(grid, visited, i - 1, j - 1);
    dfs(grid, visited, i - 1, j + 1);
    dfs(grid, visited, i + 1, j - 1);
    dfs(grid, visited, i + 1, j + 1);
}

