public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Create a boolean array to represent the maze
    boolean[] visited = new boolean[n * n];
    int startIndex = start[0] * n + start[1];
    int endIndex = end[0] * n + end[1];
    visited[startIndex] = true;

    // Use a queue to perform BFS
    Queue<Integer> queue = new LinkedList<>();
    queue.add(startIndex);

    while (!queue.isEmpty()) {
        int current = queue.poll();
        int row = current / n;
        int col = current % n;

        for (int i = 0; i < paths.length; i++) {
            int[] path = paths[i];
            int from = path[0];
            int to = path[1];

            if (from == current && !visited[to]) {
                visited[to] = true;
                queue.add(to);

                // Check if the end index is reached
                if (to == endIndex) {
                    return "can be travelled";
                }
            } else if (to == current && !visited[from]) {
                visited[from] = true;
                queue.add(from);

                // Check if the end index is reached
                if (from == endIndex) {
                    return "can be travelled";
                }
            }
        }
    }

    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
        // Create a graph to represent the interesing space
        Map<String, List<String>> graph = new HashMap<>();
        for (int[] path : paths) {
            String from = path[0] + "," + path[1];
            String to = path[2] + "," + path[3];
            graph.computeIfAbsent(from, k -> new ArrayList<>()).add(to);
            graph.computeIfAbsent(to, k -> new ArrayList<>()).add(from);
        }

        // Helper method to perform DFS to find if there is a path from start to end
        return dfs(graph, start[0] + "," + start[1], end[0] + "," + end[1], new HashSet<>()) 
               ? "can be travelled" 
               : "cannot be travelled";
    }

private static boolean dfs(Map<String, List<String>> graph, String current, String target, Set<String> visited) {
        // If the current node is the target, return true
        if (current.equals(target)) {
            return true;
        }

        // If the current node is already visited, return false to avoid cycles
        if (visited.contains(current)) {
            return false;
        }

        // Mark the current node as visited
        visited.add(current);

        // Recursively visit all adjacent nodes
        for (String neighbor : graph.getOrDefault(current, Collections.emptyList())) {
            if (dfs(graph, neighbor, target, visited)) {
                return true;
            }
        }

        // Unmark the current node as visited (backtrack)
        visited.remove(current);
        return false;
    }

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
        Set<Integer> startNodeId = Arrays.asList(start[0], start[1]);
        Set<Integer> endNodeId = Arrays.asList(end[0], end[1]);
        Set<Set<Integer>> graph = new HashSet<>();

        for (int[] path : paths) {
            Set<Integer> node1 = Arrays.asList(path[0], path[1]);
            Set<Integer> node2 = Arrays.asList(path[2], path[3]);
            graph.add(node1);
            graph.add(node2);
            if (node1.equals(startNodeId) && node2.equals(endNodeId)) {
                return "can be travelled";
            }
        }

        if (graph.contains(startNodeId) && graph.contains(endNodeId)) {
            return "can be travelled";
        }

        return "cannot be travelled";
    }

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (start[0] == end[0] && start[1] == end[1]) {
        return "can be travelled";
    }

    boolean[][] isVisited = new boolean[n][n];
    isVisited[start[0]][start[1]] = true;

    return canTravelHelper(n, start, end, paths, isVisited) ? "can be travelled" : "cannot be travelled";
}

private static boolean canTravelHelper(int n, int[] current, int[] end, int[][] paths, boolean[][] isVisited) {
    for (int i = 0; i < paths.length; i++) {
        int[] path = paths[i];
        if ((path[0] == current[0] && path[1] == current[1] && path[2] == end[0] && path[3] == end[1]) ||
            (path[2] == current[0] && path[3] == current[1] && path[0] == end[0] && path[1] == end[1])) {
            return true;
        }

        if (!isVisited[path[2]][path[3]]) {
            isVisited[path[2]][path[3]] = true;
            if (canTravelHelper(n, new int[]{path[2], path[3]}, end, paths, isVisited)) {
                return true;
            }
        }
    }

    return false;
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    boolean[][] visited = new boolean[n][n];
    return dfs(start[0], start[1], end[0], end[1], paths, visited) ? "can be travelled" : "cannot be travelled";
}

private static boolean dfs(int x, int y, int endX, int endY, int[][] paths, boolean[][] visited) {
    if (x < 0 || x >= paths.length || y < 0 || y >= paths[0].length || visited[x][y] || paths[x][y] == 0) {
        return false;
    }
    if (x == endX && y == endY) {
        return true;
    }
    visited[x][y] = true;
    if (dfs(x + 1, y, endX, endY, paths, visited) ||
        dfs(x - 1, y, endX, endY, paths, visited) ||
        dfs(x, y + 1, endX, endY, paths, visited) ||
        dfs(x, y - 1, endX, endY, paths, visited)) {
        return true;
    }
    visited[x][y] = false;
    return false;
}

