public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Build the adjacency list for the tree
    List<List<Integer>> graph = new ArrayList<>();
    for (int i = 0; i < n; i++) {
        graph.add(new ArrayList<>());
    }
    for (int[] edge : edges) {
        graph.get(edge[0]).add(edge[1]);
        graph.get(edge[1]).add(edge[0]);
    }

    // Helper function to perform DFS and calculate the minimum time
    return dfs(0, -1, graph, hasApple);
}

private int dfs(int node, int parent, List<List<Integer>> graph, boolean[] hasApple) {
    int totalTime = 0;

    // Visit all neighbors
    for (int neighbor : graph.get(node)) {
        if (neighbor == parent) continue; // Skip the parent node to avoid cycles
        int time = dfs(neighbor, node, graph, hasApple);
        if (time > 0 || hasApple[neighbor]) {
            totalTime += time + 2; // Add 2 units of time for the往返path
        }
    }

    return totalTime;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
        // Build the tree as an adjacency list
        List<List<Integer>> tree = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            tree.add(new ArrayList<>());
        }
        for (int[] edge : edges) {
            tree.get(edge[0]).add(edge[1]);
            tree.get(edge[1]).add(edge[0]);
        }

        // Helper function to perform DFS and calculate the minimum time
        boolean[] visited = new boolean[n];
        int time = dfs(0, tree, hasApple, visited);
        return Math.max(0, time - 2); // Subtract 2 to avoid counting the initial and final visit
    }

private int dfs(int node, List<List<Integer>> tree, boolean[] hasApple, boolean[] visited) {
        if (visited[node]) {
            return 0;
        }
        visited[node] = true;

        int time = 0;
        for (int neighbor : tree.get(node)) {
            time += dfs(neighbor, tree, hasApple, visited);
        }

        // If this node has an apple or its subtree has apples, add 2 to the time (one for going down and one for coming up)
        if (hasApple[node] || time > 0) {
            time += 2;
        }

        return time;
    }

