private int[] dfs(int node, List<List<Integer>> map, boolean[] hasApple, boolean[] visited) {
    visited[node] = true;
    int totalTime = 0;

    for (int neighbor : map.get(node)) {
        if (!visited[neighbor]) {
            int[] result = dfs(neighbor, map, hasApple, visited);
            totalTime += result[0];
            if (result[1] || hasApple[neighbor]) {
                totalTime += 2; // 1 second to go and 1 second to return
            }
        }
    }

    return new int[]{totalTime, hasApple[node] || totalTime > 0};
}

