public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }
    for (int i = 0; i < (1 << n); i++) {
        int sum1 = 0;
        int count1 = 0;
        for (int j = 0; j < n; j++) {
            if ((i & (1 << j)) != 0) {
                sum1 += nums[j];
                count1++;
            }
        }
        if (count1 > 0 && count1 < n && sum1 * n == count1 * sum) {
            return true;
        }
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n <= 1) return false;

    int sum = 0;
    for (int num : nums) {
        sum += num;
    }

    Set<Double>[] possibleAverages = new Set[n / 2 + 1];
    for (int i = 0; i <= n / 2; i++) {
        possibleAverages[i] = new HashSet<>();
    }

    possibleAverages[0].add(0.0);

    for (int num : nums) {
        for (int i = n / 2; i >= 1; i--) {
            for (double avg : possibleAverages[i - 1]) {
                possibleAverages[i].add(avg + (double) num / i);
            }
        }
    }

    for (double avg : possibleAverages[n / 2]) {
        if (avg * n == sum) continue;
        if (possibleAverages[n - n / 2].contains(sum - avg * n)) {
            return true;
        }
    }

    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n == 1) {
        return false;
    }

    int totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }

    for (int sizeA = 1; sizeA <= n / 2; sizeA++) {
        if (totalSum * sizeA % n == 0) {
            if (findSubsetWithSum(nums, sizeA, totalSum * sizeA / n)) {
                return true;
            }
        }
    }
    return false;
}

private boolean findSubsetWithSum(int[] nums, int size, int target) {
    if (size == 0) {
        return target == 0;
    }
    if (nums.length == 0) {
        return false;
    }

    if (nums[nums.length - 1] > target) {
        return findSubsetWithSum(nums, size, target);
    }

    return findSubsetWithSum(nums, size - 1, target - nums[nums.length - 1]) || findSubsetWithSum(nums, size, target);
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n == 1) {
        return false;
    }

    int totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }

    for (int i = 1; i <= n / 2; i++) {
        if (totalSum * i % n == 0) {
            if (hasSum(nums, i, totalSum * i / n)) {
                return true;
            }
        }
    }

    return false;
}

private boolean hasSum(int[] nums, int k, int target) {
    int n = nums.length;
    boolean[][] dp = new boolean[k + 1][target + 1];

    for (int i = 0; i <= k; i++) {
        dp[i][0] = true;
    }

    for (int i = 1; i <= k; i++) {
        for (int j = 1; j <= target; j++) {
            dp[i][j] = dp[i - 1][j];
            if (nums[i - 1] <= j) {
                dp[i][j] = dp[i][j] || dp[i - 1][j - nums[i - 1]];
            }
        }
    }

    return dp[k][target];
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n <= 1) return false;

    int sum = 0;
    for (int num : nums) {
        sum += num;
    }

    boolean[] possibleAverages = new boolean[2 * sum + 1];

    for (int i = 0; i < (1 << n); i++) {
        int groupSum = 0;
        int groupCount = 0;
        for (int j = 0; j < n; j++) {
            if ((i & (1 << j)) != 0) {
                groupSum += nums[j];
                groupCount++;
            }
        }
        if (groupCount > 0 && groupSum * (n - groupCount) == groupCount * sum) {
            return true;
        }
        possibleAverages[groupSum + sum] = true;
    }

    for (int i = 1; i < n; i++) {
        for (int j = 0; j < 2 * sum + 1; j++) {
            if (possibleAverages[j]) {
                possibleAverages[j - i] = true;
            }
        }
        if (possibleAverages[sum * i / n]) {
            return true;
        }
    }

    return false;
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    if (n == 1) return cost[0];

    int[] dp = new int[n];
    dp[0] = cost[0];
    dp[1] = cost[1];

    for (int i = 2; i < n; i++) {
        dp[i] = Math.min(dp[i-1], dp[i-2]) + cost[i];
    }

    return Math.min(dp[n-1], dp[n-2]);
}

