public boolean hasAllCodes(String s, int k) {
    if (s.length() < Math.pow(2, k)) {
        return false;
    }

    java.util.Set<String> substrings = new java.util.HashSet<>();
    for (int i = 0; i <= s.length() - k; i++) {
        substrings.add(s.substring(i, i + k));
    }

    return substrings.size() == Math.pow(2, k);
}

public boolean hasAllCodes(String s, int k) {
    if (s.length() < Math.pow(2, k)) {
        return false;
    }

    int target = 1 << k;
    boolean[] seen = new boolean[target];

    int unique = 0;
    for (int i = 0; i < s.length(); i++) {
        int code = 0;
        for (int j = i; j < Math.min(s.length(), i + k); j++) {
            code = (code << 1) | (s.charAt(j) - '0');
        }

        if (seen[code]) {
            continue;
        }

        seen[code] = true;
        unique++;
        if (unique == target) {
            return true;
        }
    }

    return false;
}

