public boolean hasAllCodes(String s, int k) {
    if (s.length() - k + 1 < 1 << k) {
        return false;
    }

    boolean[] present = new boolean[1 << k];
    int count = 0;
    for (int i = 0; i < s.length(); i++) {
        int val = (present[i & ((1 << k) - 1)] << 1) | (s.charAt(i) - '0');
        if (!present[val]) {
            present[val] = true;
            count++;
        }
        if (count == 1 << k) {
            return true;
        }
    }

    return false;
}

