public int minInsertions(String s) {
    int open = 0; // Count of unmatched '('
    int close = 0; // Count of unmatched ')'
    int insertions = 0; // Total insertions required

    for (char c : s.toCharArray()) {
        if (c == '(') {
            if (close % 2 != 0) {
                insertions++; // Add a ')'
                close--;
            }
            open++;
        } else {
            close++;
            if (close > open * 2) {
                insertions++; // Add a '('
                open++;
            }
        }
    }

    return insertions + open * 2 - close; // Total insertions
}

public int minInsertions(String s) {
    int balance = 0;
    int insert = 0;

    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);

        if (c == '(') {
            if (balance < 0) {
                insert += -balance; // Close unmatched ')'
                balance = 0;
            }
            balance++;
        } else if (c == ')') {
            balance--;
        }
    }

    if (balance < 0) {
        insert += -balance; // Close unmatched ')'
    }

    return insert + balance * 2; // Total insertions needed
}

public int minInsertions(String s) {
    int balance = 0;
    int insertions = 0;

    for (int i = 0; i < s.length(); i++) {
        char current = s.charAt(i);

        if (current == '(') {
            balance++;
        } else {
            balance--;
            if (i + 1 < s.length() && s.charAt(i + 1) == ')') {
                i++;
            } else {
                insertions++;
            }

            if (balance < 0) {
                balance = 0;
                insertions++;
            }
        }
    }

    return insertions + balance * 2;
}

public int minInsertions(String s) {
    int bal = 0; // Balance of parentheses
    int ans = 0; // Number of insertions

    for (int i = 0; i < s.length(); ++i) {
        char c = s.charAt(i);
        if (c == '(') {
            bal++;
        } else {
            if (bal > 0) {
                bal--;
            } else {
                ans++;
            }
            if (i + 1 < s.length() && s.charAt(i + 1) == ')') {
                i++;
            } else {
                ans++;
            }
        }
    }

    return ans + bal * 2;
}

public int minInsertions(String s) {
    int left = 0;
    int right = 0;
    int insertions = 0;

    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);

        if (c == '(') {
            if (right % 2 == 1) {
                insertions++;
                right--;
            }
            left++;
        } else if (c == ')') {
            right++;

            if (right > left * 2) {
                insertions++;
                left++;
            }
        }
    }

    return insertions + left * 2 - right;
}

