    if (n <= 1) {
        return 0;
    }

    int[] arr = new int[n];
    for (int i = 0; i < n; i++) {
        arr[i] = (2 * i) + 1;
    }

    int target = arr[n / 2];
    int operations = 0;

    for (int i = 0; i < n / 2; i++) {
        operations += target - arr[i];
    }

