public int minOperations(int n) {
    // Calculate the target value for all elements
    int target = n;
    // Calculate the sum of all elements in the array
    int sum = n * (2 * n - 1) / 2;
    // Calculate the sum of the first n/2 elements
    int sumFirstHalf = n * n / 2;
    // The result is the difference between the sum of the first half and the target value
    return sumFirstHalf - target * n / 2;
}

