    int maxSum = 0;
    int minSum = 0;
    int maxAbsoluteSum = 0;

    for (int num : nums) {
        maxSum = Math.max(maxSum + num, 0);
        minSum = Math.min(minSum + num, 0);
        maxAbsoluteSum = Math.max(Math.max(maxAbsoluteSum, maxSum), Math.abs(minSum));
    }

    return maxAbsoluteSum;
}

public int maxAbsoluteSum(int[] nums) {
    int maxSum = 0;
    int minSum = 0;
    int currentSum = 0;

    for (int num : nums) {
        currentSum += num;
        maxSum = Math.max(maxSum, currentSum);
        minSum = Math.min(minSum, currentSum);
        currentSum = Math.max(0, currentSum);
    }

    return Math.max(maxSum, Math.abs(minSum));
}

public int maxAbsoluteSum(int[] nums) {
    int maxSum = 0;
    int minSum = 0;
    int currentMax = 0;
    int currentMin = 0;

    for (int num : nums) {
        currentMax = Math.max(num, currentMax + num);
        maxSum = Math.max(maxSum, currentMax);

        currentMin = Math.min(num, currentMin + num);
        minSum = Math.min(minSum, currentMin);
    }

    return Math.max(maxSum, -minSum);
}

public int findMinFibonacciNumbers(int k) {
    if (k == 0) return 0;

    int[] fib = new int[2];
    fib[0] = 1;
    fib[1] = 1;
    while (fib[1] < k) {
        int next = fib[0] + fib[1];
        fib[0] = fib[1];
        fib[1] = next;
    }

    return 1 + findMinFibonacciNumbers(k - fib[0]);
}

public int findMinFibonacciNumbers(int k) {
    if (k <= 0) {
        return 0;
    }

    // Generate Fibonacci numbers up to k
    List<Integer> fibonacci = new ArrayList<>();
    int a = 1, b = 1;
    fibonacci.add(a);
    fibonacci.add(b);
    while (b < k) {
        int next = a + b;
        a = b;
        b = next;
        fibonacci.add(b);
    }

    // Find the minimum number of Fibonacci numbers whose sum is equal to k
    int count = 0;
    int index = fibonacci.size() - 1;
    while (k > 0 && index >= 0) {
        if (fibonacci.get(index) <= k) {
            k -= fibonacci.get(index);
            count++;
        }
        index--;
    }

    return count;
}

public int findMinFibonacciNumbers(int k) {
    List<Integer> fibs = new ArrayList<>();
    fibs.add(1);
    fibs.add(1);

    // Generate Fibonacci numbers up to k
    while (fibs.get(fibs.size() - 1) < k) {
        int size = fibs.size();
        fibs.add(fibs.get(size - 1) + fibs.get(size - 2));
    }

    int count = 0;
    // Use the largest Fibonacci numbers first
    for (int i = fibs.size() - 1; i >= 0 && k > 0; i--) {
        if (fibs.get(i) <= k) {
            k -= fibs.get(i);
            count++;
        }
    }

    return count;
}

public static int findMinFibonacciNumbers(int k) {
        if (k <= 1) {
            return k;
        }

        List<Integer> fibonacciNumbers = new ArrayList<>();
        int a = 1, b = 1;
        fibonacciNumbers.add(a);
        while (b <= k) {
            fibonacciNumbers.add(b);
            int next = a + b;
            a = b;
            b = next;
        }

        int count = 0;
        for (int i = fibonacciNumbers.size() - 1; i >= 0; i--) {
            if (fibonacciNumbers.get(i) <= k) {
                count++;
                k -= fibonacciNumbers.get(i);
            }
            if (k == 0) {
                break;
            }
        }

        return count;
    }

