public int maxUniqueSplit(String s) {
    Set<String> uniqueSubstrings = new HashSet<>();
    return backtrack(s, 0, uniqueSubstrings);
}

private int backtrack(String s, int start, Set<String> uniqueSubstrings) {
    if (start == s.length()) {
        return uniqueSubstrings.size();
    }
    int maxUnique = 0;
    for (int i = start + 1; i <= s.length(); i++) {
        String substring = s.substring(start, i);
        if (uniqueSubstrings.add(substring)) {
            maxUnique = Math.max(maxUnique, backtrack(s, i, uniqueSubstrings));
            uniqueSubstrings.remove(substring);
        }
    }
    return maxUnique;
}

public int maxUniqueSplit(String s) {
    return backtrack(s, 0, new HashSet<>());
}

private int backtrack(String s, int start, Set<String> set) {
    if (start == s.length()) {
        return set.size();
    }

    int maxUnique = 0;
    for (int end = start + 1; end <= s.length(); end++) {
        String substring = s.substring(start, end);
        if (!set.contains(substring)) {
            set.add(substring);
            maxUnique = Math.max(maxUnique, backtrack(s, end, set));
            set.remove(substring);
        }
    }

    return maxUnique;
}

