    Set<String> seen = new HashSet<>();
    return backtrack(s, seen);
}

private int backtrack(String s, Set<String> seen) {
    if (s.isEmpty()) {
        return 0;
    }

    int maxSplits = 0;
    for (int i = 1; i <= s.length(); i++) {
        String prefix = s.substring(0, i);
        if (seen.add(prefix)) {
            maxSplits = Math.max(maxSplits, 1 + backtrack(s.substring(i), seen));
            seen.remove(prefix);
        }
    }
    return maxSplits;
}

