    int index = n - 1; // Start from the end of the array
    while (k > 0) {
        int toAdd = Math.min(k, 25); // We can add at most 25 to get to 'z'
        result[index] += toAdd;
        k -= toAdd;
        index--;
    }

    return new String(result);
}

