public static List<Integer> findSteppingNumbers(int low, int high) {
        List<Integer> steppingNumbers = new ArrayList<>();
        if (low <= 0) steppingNumbers.add(0);
        Queue<Integer> queue = new LinkedList<>();
        for (int i = 1; i <= 9; i++) {
            queue.offer(i);
        }

        while (!queue.isEmpty()) {
            int num = queue.poll();
            if (num >= low && num <= high) {
                steppingNumbers.add(num);
            }
            int lastDigit = num % 10;
            if (lastDigit > 0) {
                int nextNum = num * 10 + (lastDigit - 1);
                if (nextNum <= high) {
                    queue.offer(nextNum);
                }
            }
            if (lastDigit < 9) {
                int nextNum = num * 10 + (lastDigit + 1);
                if (nextNum <= high) {
                    queue.offer(nextNum);
                }
            }
        }

        Collections.sort(steppingNumbers);
        return steppingNumbers;
    }

public static List<Integer> findSteppingNumbers(int low, int high) {
        List<Integer> steppingNumbers = new ArrayList<>();
        if (high < 10) {
            for (int i = low; i <= high; i++) {
                steppingNumbers.add(i);
            }
            return steppingNumbers;
        }

        Queue<Integer> queue = new LinkedList<>();
        for (int i = 1; i <= 9; i++) {
            queue.offer(i);
        }

        while (!queue.isEmpty()) {
            int num = queue.poll();
            if (num > high) break;
            int lastDigit = num % 10;
            if (num >= low) steppingNumbers.add(num);

            if (lastDigit > 0) queue.offer(num * 10 + (lastDigit - 1));
            if (lastDigit < 9) queue.offer(num * 10 + (lastDigit + 1));
        }

        return steppingNumbers;
    }

