public static int countDigitOne(int n) {
        if (n <= 0) {
            return 0;
        }

        String str = Integer.toString(n);
        int length = str.length();
        int count = 0;

        for (int i = 0; i < length; i++) {
            int digit = str.charAt(i) - '0';
            int higher = str.substring(0, i).isEmpty() ? 0 : Integer.parseInt(str.substring(0, i));
            int lower = str.substring(i + 1).isEmpty() ? 0 : Integer.parseInt(str.substring(i + 1));

            if (digit == 0) {
                count += higher * Math.pow(10, length - i - 1);
            } else if (digit == 1) {
                count += higher * Math.pow(10, length - i - 1) + lower + 1;
            } else {
                count += (higher + 1) * Math.pow(10, length - i - 1);
            }
        }

        return count;
    }

