private static int countOnes(int num) {
    int ones = 0;
    while (num > 0) {
        if (num % 10 == 1) {
            ones++;
        }
        num /= 10;
    }
    return ones;
}

public static int countDigitOne(int n) {
    if (n <= 0) {
        return 0;
    }

    int count = 0;
    long factor = 1;
    int currentDigit = 0;
    int lowerNumbers = 0;
    int higherNumbers = 0;

    while (n / factor != 0) {
        currentDigit = (int) (n / factor) % 10;
        lowerNumbers = (int) (n - (n / factor) * factor);
        higherNumbers = (int) (n / (factor * 10));

        if (currentDigit == 0) {
            count += higherNumbers * factor;
        } else if (currentDigit == 1) {
            count += higherNumbers * factor + lowerNumbers + 1;
        } else {
            count += (higherNumbers + 1) * factor;
        }

        factor *= 10;
    }

    return count;
}

