static int backtrack(int[] A, int index, boolean[] used) {
    if (index == A.length - 1) return 1;
    int count = 0;
    for (int i = 0; i < A.length; i++) {
        if (used[i] || (index > 0 && !isPerfectSquare(A[index - 1] + A[i]))) continue;
        used[i] = true;
        count += backtrack(A, index + 1, used);
        used[i] = false;
    }
    return count;
}

