private static void backtrack(int[] A, int start, int count) {
    if (start == A.length - 1) {
        count++;
        return;
    }

    for (int i = start + 1; i < A.length; i++) {
        if (isPerfectSquare(A[start] + A[i])) {
            swap(A, start + 1, i);
            backtrack(A, start + 1, count);
            swap(A, start + 1, i); // backtrack
        }
    }
}

private static void swap(int[] A, int i, int j) {
    int temp = A[i];
    A[i] = A[j];
    A[j] = temp;
}

