private static void backtrack(int[] A, boolean[] visited, int index, int[] count) {
    if (index == A.length - 1) {
        count[0]++;
        return;
    }

    for (int i = 0; i < A.length; i++) {
        if (!visited[i] && (index == 0 || isPerfectSquare(A[index - 1] + A[i]))) {
            visited[i] = true;
            backtrack(A, visited, index + 1, count);
            visited[i] = false;
        }
    }
}

