    }

    int n = A.length;
    boolean[][] dp = new boolean[n][A.length];
    for (int i = 0; i < n; i++) {
        for (int j = i; j < n; j++) {
            int sum = A[i] + A[j];
            int sqrt = (int) Math.sqrt(sum);
            if (sqrt * sqrt == sum) {
                dp[i][j] = true;
            }
        }
    }

    int[] dpCount = new int[n];
    for (int i = 0; i < n; i++) {
        dpCount[i] = 1;
        for (int j = 0; j < i; j++) {
            if (dp[j][i]) {
                dpCount[i] = Math.max(dpCount[i], dpCount[j] + 1);
            }
        }
    }

    int maxLen = 0;
    for (int count : dpCount) {
        maxLen = Math.max(maxLen, count);
    }

    return (int) Math.pow(n, n - maxLen);
}

