private static int calculateSquarePermutations(int[] A, int start, boolean[] used) {
    if (start == A.length) {
        return 1;
    }

    int count = 0;
    for (int i = 0; i < A.length; i++) {
        if (!used[i] && isPerfectSquare(A[start] + A[i])) {
            used[i] = true;
            count += calculateSquarePermutations(A, start + 1, used);
            used[i] = false;
        }
    }

    return count;
}

