        // If no such digit is found, return -1
        if (i == -1) {
            return -1;
        }

        // Find the smallest digit on the right side of (i-th digit) which is greater than digits[i]
        int j;
        for (j = digits.length - 1; j > i; j--) {
            if (digits[j] > digits[i]) {
                break;
            }
        }

        // Swap the found digits
        char temp = digits[i];
        digits[i] = digits[j];
        digits[j] = temp;

        // Sort the digits after the (i-th digit) in ascending order
        Arrays.sort(digits, i + 1, digits.length);

        return Integer.parseInt(new String(digits));
    }

