public static int findSmallestInteger(int n) {
    char[] digits = String.valueOf(n).toCharArray();
    int len = digits.length;

    // Find the first digit that can be swapped to make the number smaller
    for (int i = len - 2; i >= 0; i--) {
        if (digits[i] < digits[i + 1]) {
            // Find the smallest digit to the right of digits[i] that is greater than digits[i]
            int minIndex = i + 1;
            for (int j = i + 2; j < len; j++) {
                if (digits[j] > digits[i] && digits[j] < digits[minIndex]) {
                    minIndex = j;
                }
            }

            // Swap the digits
            char temp = digits[i];
            digits[i] = digits[minIndex];
            digits[minIndex] = temp;

            // Sort the digits to the right of the current index in ascending order
            Arrays.sort(digits, i + 1, len);

            // Convert the digits back to an integer and return
            return Integer.parseInt(new String(digits));
        }
    }

    // If no such swap can be found, return -1
    return -1;
}

