        for (char choice : choices) {
            if (left == 0 && choice == '0') continue; // Avoid leading zero
            sb.append(choice);
            if (choice == '6') {
                sb.append('9');
                backtrack(result, sb, left - 1, right - 2);
                sb.deleteCharAt(sb.length() - 1);
            } else if (choice == '9') {
                sb.append('6');
                backtrack(result, sb, left - 1, right - 2);
                sb.deleteCharAt(sb.length() - 1);
            } else {
                backtrack(result, sb, left - 1, right - 1);
            }
            sb.deleteCharAt(sb.length() - 1);
        }
    }

