private static void dfs(int num, int n, List<Integer> result) {
        if (num > n) {
            return;
        }
        result.add(num);
        for (int i = 0; i <= 9; i++) {
            int nextNum = num * 10 + i;
            if (nextNum > n) {
                return;
            }
            dfs(nextNum, n, result);
        }
    }

