public static int minPerfectSquareSum(int n) {
    if (n <= 3) {
        return n;
    }

    int[] dp = new int[n + 1];
    for (int i = 0; i <= n; i++) {
        dp[i] = i;
    }

    for (int i = 4; i <= n; i++) {
        for (int j = 1; j * j <= i; j++) {
            dp[i] = Math.min(dp[i], dp[i - j * j] + 1);
        }
    }
    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    // Edge case: if n is 0, no perfect squares are needed
    if (n == 0) return 0;

    // dp array to store the minimum perfect square sum for each number up to n
    int[] dp = new int[n + 1];

    // Initialize the dp array with a large value (infinity)
    for (int i = 1; i <= n; i++) {
        dp[i] = Integer.MAX_VALUE;
    }

    // Base case: 0 perfect squares are needed to sum up to 0
    dp[0] = 0;

    // Fill the dp array
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j * j <= i; j++) {
            dp[i] = Math.min(dp[i], dp[i - j * j] + 1);
        }
    }

    // The answer is the minimum number of perfect squares needed to sum up to n
    return dp[n];
}

