    }

    int[] dp = new int[n + 1];
    for (int i = 1; i <= n; i++) {
        dp[i] = i; // Initialize with the maximum possible (i.e., i itself is the sum of 1s)
        for (int j = 1; j * j <= i; j++) {
            dp[i] = Math.min(dp[i], dp[i - j * j] + 1);
        }
    }

    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    // Create a bottom-up DP array to store the minimum number of perfect square sums
    int[] dp = new int[n + 1];
    // Initialize the array with a large value (n is the maximum possible sum of 1^2)
    for (int i = 1; i <= n; i++) {
        dp[i] = i;
    }

    // Build the DP array from 1 to n
    for (int i = 2; i <= n; i++) {
        for (int j = 1; j * j <= i; j++) {
            dp[i] = Math.min(dp[i], dp[i - j * j] + 1);
        }
    }

    // Return the minimum number of perfect square sums for n
    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    if (n <= 3) return n;

    int[] dp = new int[n + 1];
    for (int i = 0; i <= n; i++) {
        dp[i] = i; // Initial assumption: the worst case is using 1 as the only square (i times)
    }

    for (int i = 4; i <= n; i++) {
        for (int j = 1; j * j <= i; j++) {
            dp[i] = Math.min(dp[i], dp[i - j * j] + 1);
        }
    }

    return dp[n];
}

public static String reverseWords(String s) {
